using System.Collections.ObjectModel;
namespace NeoPlayer.Windows.Models;

public sealed record Song(long Id,string Path,string Title,string Artist,string Album,string AlbumArtist,string Genre,int Year,long DurationMs,int TrackNumber,int DiscNumber,string Composer,int Bitrate,string MimeType,long SizeBytes,string RelativePath,long DateAdded,long DateModified,string CustomArtworkPath="")
{
    public string DisplayArtist => string.IsNullOrWhiteSpace(Artist) ? "Unknown artist" : Artist;
    public string DurationText => TimeSpan.FromMilliseconds(DurationMs).ToString(DurationMs>=3600000?@"h\:mm\:ss":@"m\:ss");
}
public sealed record Playlist(long Id,string Title,string Description,string? ArtworkPath,long CreatedAt,long? FolderId,int CustomOrder);
public sealed record PlaylistFolder(long Id,string Title,long? ParentId,int Position,long CreatedAt);
public sealed record Category(long Id,string Title,string Description,string? ArtworkPath,long CreatedAt);
public sealed record ListeningHistory(long SongId,int PlayCount,int SkipCount,long TotalListeningMs,long LastPlayedAt);
public sealed record LyricsRecord(long SongId,string Original,string Translation,string Romanization,bool Synchronized,string Source,long UpdatedAt);
public sealed record EqProfile(long SongId,string Preset,float Bass,float Virtualizer,float LoudnessDb,float[] Bands);
public sealed record TrackVisualProfile(long SongId,string? CanvasPath,bool CanvasEnabled,string CanvasFit,long CanvasStartMs,long CanvasEndMs,float CanvasPlaybackSpeed,string ThemeMode,int AccentArgb,int BackgroundArgb,int SecondaryArgb,string VisualizerMode,float VisualizerSensitivity,float AnimationIntensity,string BackgroundImagePath,string BackgroundMode,float BackgroundOpacity,int BackgroundBlurDp,long UpdatedAt);
public sealed record AudioAnalysis(long SongId,float IntegratedLufs,float PeakDb,float Bpm,int GainMb,long AnalyzedAt);
public sealed record AdvancedAudioAnalysis(long SongId,float Bpm,float BeatIntervalMs,float BeatOffsetMs,float BeatConfidence,int PhraseLengthBeats,float PhraseOffsetMs,float PhraseConfidence,string MusicalKey,string CamelotKey,float KeyConfidence,float Energy,float Valence,float Danceability,float SpectralCentroidHz,float DynamicRangeDb,string Mood,string BeatGridJson,long AnalyzedAt);
public sealed record ReplayGain(long SongId,float? TrackGainDb,float? AlbumGainDb,float? TrackPeak,float? R128TrackGainDb,string Source,long ScannedAt){public float? PreferredGainDb=>R128TrackGainDb??TrackGainDb??AlbumGainDb;}
public sealed record RecommendationFeedback(long SongId,int Boost,int DismissCount,long LastSeededAt);
public sealed record OfflineSpeechModel(string Id,string DisplayName,string Language,string LocalPath,int SampleRate,long ImportedAt);
public sealed record OfflineTranscript(long SongId,string Engine,string ModelId,string Language,string PlainText,string LrcText,string WordTimedJson,float AverageConfidence,long GeneratedAt);
public sealed record OfflineBackupEntry(long SongId,int Position,float Score,string Reason,string Mood,string Genre,long GeneratedAt);
public sealed record QueueEntry(int Position,long SongId);
public sealed record LrcLine(long TimeMs,string Text,string Translation="",string Romanization="");
public sealed record SpectrumFrame(float[] Values,long TimestampMs);

public enum RepeatMode { Off, All, One }
public enum ThemeMode { System, Dark, Light, Amoled }
public enum Accent { Orange, Green, Red, Blue, Custard, Purple, Cyan, Pink, Indigo, Teal, Gold, Custom }
public enum LibraryViewMode { List, Grid }
public enum PageKind { Home, Search, Library, Settings }

